<?php global $wpdb; $qs=$wpdb->get_results("SELECT id,title,quiz_json,level FROM {$wpdb->prefix}quran_quizzes ORDER BY id DESC LIMIT 20",ARRAY_A); ?><!doctype html><html><body><h1>Quiz Engine</h1><?php foreach($qs as $q): ?><section><h3><?php echo esc_html($q['title']); ?></h3><small><?php echo esc_html($q['level']); ?></small><pre><?php echo esc_html((string)$q['quiz_json']); ?></pre></section><?php endforeach; ?></body></html>
